apiVersion: apprafter.io/v1alpha1
kind: Application
metadata: {
    name:      "billing-api"
    namespace: "prod"
}

spec: {
    base: {
        image:    "ghcr.io/me/billing:v1.4.2"
        replicas: 3

        expose: {
            port:     8080
            network:  "public"
            hostname: "billing.example.com"
        }

        needs: {
            pg: {size: "small"}
        }

        env: {
            DATABASE_URL: claim.pg.url
            STRIPE_KEY:   secret: "stripe/api-key"
            LOG_LEVEL:    "info"
        }
    }

    environments: {
        dev: {
            replicas: 1
            expose: {
                port:    8080
                network: "internal"
            }
        }
        prod: {
            replicas: 3
        }
    }
}
